#include <cstdio>
#include <vector>
#include <queue>
#include <functional>
#include <cstring>

int main() {
    int q;
    scanf("%d", &q);
    std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
    for (int i = 0; i < q; ++i) {
        char op[16];
        scanf("%s", op);
        if (strcmp(op, "push") == 0) {
            int x;
            scanf("%d", &x);
            pq.push(x);
        } else if (strcmp(op, "pop") == 0) {
            printf("%d\n", pq.top());
            pq.pop();
        } else if (strcmp(op, "top") == 0) {
            printf("%d\n", pq.top());
        } else if (strcmp(op, "size") == 0) {
            printf("%d\n", (int)pq.size());
        }
    }
    return 0;
}
